<?php require 'config/database.php';require 'config/app.php';if(!isset($_SESSION['player_id'])){flash('warning','Log in before registering a squad.');go('login.php');}$tid=(int)($_GET['tournament_id']??$_POST['tournament_id']??0);$s=$pdo->prepare("SELECT * FROM tournaments WHERE tournament_id=?");$s->execute([$tid]);$t=$s->fetch();if(!$t)go('tournaments.php');$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$team=trim($_POST['team']??'');$captain=trim($_POST['captain_uid']??'');$ps=[];for($i=1;$i<=4;$i++)$ps[]=['name'=>trim($_POST['pn'.$i]??''),'uid'=>trim($_POST['uid'.$i]??''),'ign'=>trim($_POST['ign'.$i]??'')];if(mb_strlen($team)<2)$errors[]='Team name must be at least 2 characters.';if(!preg_match('/^[0-9]{5,20}$/',$captain))$errors[]='Enter a valid captain BGMI ID.';foreach($ps as $i=>$p)if(mb_strlen($p['name'])<2||!preg_match('/^[0-9]{5,20}$/',$p['uid'])||mb_strlen($p['ign'])<2)$errors[]='Complete all fields for player '.($i+1).'.';if(count(array_unique(array_column($ps,'uid')))!==4)$errors[]='Each player must have a unique BGMI ID.';$c=$pdo->prepare("SELECT COUNT(*) FROM registrations WHERE tournament_id=? AND status IN ('confirmed','pending_payment','payment_review')");$c->execute([$tid]);if((int)$c->fetchColumn()>=(int)$t['max_teams'])$errors[]='This tournament is full.';if($t['status']!=='open'||strtotime($t['registration_deadline'])<time())$errors[]='Registration is closed.';if(!$errors){try{$pdo->beginTransaction();$code='BA-'.strtoupper(bin2hex(random_bytes(4)));$s=$pdo->prepare("INSERT INTO registrations(registration_code,tournament_id,player_id,team_name,captain_uid,status) VALUES(?,?,?,?,?,'pending_payment')");$s->execute([$code,$tid,(int)$_SESSION['player_id'],$team,$captain]);$rid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO registration_players(registration_id,player_name,bgmi_uid,in_game_name,role) VALUES(?,?,?,?,?)");foreach($ps as $i=>$p)$ins->execute([$rid,$p['name'],$p['uid'],$p['ign'],$i===0?'Captain':'Player']);$pay=$pdo->prepare("INSERT INTO payments(registration_id,amount,status) VALUES(?,?,?)");$pay->execute([$rid,$t['entry_fee'],$t['entry_fee']>0?'created':'not_required']);if((float)$t['entry_fee']<=0){$pdo->prepare("UPDATE registrations SET status='confirmed' WHERE registration_id=?")->execute([$rid]);}$pdo->commit();go($t['entry_fee']>0?'payment.php?id='.$rid:'entry.php?id='.$rid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Could not save registration. Team name may already be registered.';}}}$pageTitle='Register squad';require 'includes/header.php';?>
<section class="page-hero compact"><div class="eyebrow">SQUAD ENTRY / <?=e($t['name'])?></div><h1>BUILD YOUR <span>SQUAD.</span></h1><p>Enter accurate player details. Four unique BGMI IDs are required.</p></section><div class="form-layout section"><section class="box"><div class="eyebrow">TEAM DETAILS</div><h2>Squad registration</h2><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="tournament_id" value="<?=$tid?>"><label>Team name<input name="team" required value="<?=e($_POST['team']??'')?>"></label><label>Captain BGMI ID<input name="captain_uid" required pattern="[0-9]{5,20}" value="<?=e($_POST['captain_uid']??'')?>"></label><div class="eyebrow">ROSTER / FOUR PLAYERS</div><?php for($i=1;$i<=4;$i++):?><div class="player-box"><b>0<?=$i?> / PLAYER <?=$i?><?=$i===1?' · CAPTAIN':''?></b><div class="row g-3 mt-1"><div class="col-md-6"><label>Player name<input name="pn<?=$i?>" required value="<?=e($_POST['pn'.$i]??'')?>"></label></div><div class="col-md-6"><label>In-game name<input name="ign<?=$i?>" required value="<?=e($_POST['ign'.$i]??'')?>"></label></div><div class="col-12"><label>BGMI ID<input name="uid<?=$i?>" required pattern="[0-9]{5,20}" value="<?=e($_POST['uid'.$i]??'')?>"></label></div></div></div><?php endfor;?><div class="price-line"><span>ENTRY FEE / SQUAD</span><b><?=$t['entry_fee']>0?'₹'.number_format($t['entry_fee']):'FREE'?></b></div><button class="btn btn-hot btn-lg w-100">Continue ↗</button></form></section><aside class="box"><div class="eyebrow">ENTRY SUMMARY</div><h3><?=e($t['name'])?></h3><p><?=e($t['description'])?></p><div class="summary-line"><span>Prize pool</span><b>₹<?=number_format($t['prize_pool'])?></b></div><div class="summary-line"><span>Start date</span><b><?=e(date('d M Y',strtotime($t['tournament_date'])))?></b></div><div class="notice">✦ Use valid BGMI IDs. Paid entries stay pending until payment is reviewed.</div></aside></div><?php require 'includes/footer.php';?>
